// Generates the C# and TypeScript protocol code from schema/protocol.v1.json (spec §70.1, decisions.md).
//   node schema/codegen.mjs           write the generated files
//   node schema/codegen.mjs --check   exit 1 if a generated file is stale
//
// Root: "x-protocol-version" (positive integer) and "x-protocol-min-version" (1..x-protocol-version, the oldest version
// the bridge and native host still serve — plan-phase2 D4), "x-tools", "$defs", and optionally "x-relay-close-codes":
// {UPPER_SNAKE: {code: integer 4500..4599, unique, description}} — the relay's own WebSocket close codes (plan-relay
// S1), never the app's 4001–4007.
// Supported schema subset. Every node is checked against a key whitelist, so a keyword the generators do not
// enforce (maxLength on an unsupported node, format, oneOf, …) fails codegen instead of silently drifting:
//   $defs entry = string enum {type:"string", enum:[...]}
//              | object {type:"object", additionalProperties:false, required:[...], properties:{...}}
//                (a WebSocket message when it has "x-message", a native-messaging message when it has
//                "x-native-message", a relay control message when it has "x-relay-message" — exactly one channel;
//                properties.type = {const: <that name>}; names are unique across the channels, so no message is
//                valid on two — plan-native ND3, plan-relay S1); a WebSocket message may
//                carry "x-since": the first protocol version that has it (1..x-protocol-version, default 1 —
//                plan-phase3 D2): the bridge sends and the extension accepts it only on a link of that version or newer;
//                a CMD_* message may carry "x-write": true — a command with a side effect (ledger, serializer, never
//                resent across epochs — plan-phase5a D2, seam S2); absent = a read
//   property   = {type:"string", pattern? , maxLength?}   — at least one of them (bounded size, spec §71.1)
//              | {type:"integer", minimum?, maximum?}      — safe integer range (|x| ≤ 2^53−1) on both sides, plus
//                                                            the optional inclusive bounds (safe integers, min ≤ max)
//              | {type:"boolean"} | {$ref:"#/$defs/X"}
//              | {type:"array", items:<property>, maxItems, minItems?} — maxItems required; minItems an integer in
//                                                            0..maxItems (default 0 — plan-phase5b P1)
//              | {const:"..."}                             — message type only
//   optional   = not listed in "required"; an optional member is absent, never null (JSON null is never valid)
//   field since = a top-level OPTIONAL property of a WebSocket message may carry "x-since": a field newer than its
//                message (an integer in (the message's since, x-protocol-version]); not on items, not inside a $ref'd
//                def, not on the type const; emitted as FIELD_SINCE / ProtocolInfo.FieldSince (message → wire name →
//                version, only the messages that have one) — plan-phase8 D1, seam S7
//   strings    = well-formed Unicode only (no lone surrogates); patterns are anchored at the very end in C# (\z) and
//                use no shorthand class (\s \S \d \D \w \W \b \B mean other characters in .NET than in JavaScript)
//                except the "any character" idiom [\s\S] — spell the characters out (plan-phase5b P1). Only the
//                shorthand classes are checked: other syntax the engines read differently ("." and \r / U+2028,
//                \p{..}, \A \Z \G, class subtraction) is NOT refused — keep patterns to literals, [..] and quantifiers
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
export const OUTPUTS = {
  cs: join(root, "bridge/src/Panda.Protocol/Protocol/Protocol.g.cs"),
  ts: join(root, "extension/src/protocol/protocol.g.ts"),
  // plan-relay-go D7: the relay channel only (messages, their enums, close codes) for the Go port of the relay
  go: join(root, "relay-go/internal/protocol/protocol.g.go"),
};
const HEADER = "Generated by schema/codegen.mjs from schema/protocol.v1.json — do not edit.";
const ROOT_KEYS = ["$schema", "$id", "title", "description", "x-protocol-version", "x-protocol-min-version", "x-tools", "x-relay-close-codes", "$defs"];
const ENUM_KEYS = ["type", "enum", "description"];
const CHANNELS = { "x-message": "ws", "x-native-message": "native", "x-relay-message": "relay" };
const OBJECT_KEYS = ["type", "additionalProperties", "required", "properties", "description", ...Object.keys(CHANNELS), "x-since", "x-write"];
const PROP_KEYS = {
  string: ["type", "pattern", "maxLength", "description"],
  integer: ["type", "minimum", "maximum", "description"],
  boolean: ["type", "description"],
  array: ["type", "items", "maxItems", "minItems", "description"],
  ref: ["$ref", "description"],
};

function fail(msg) {
  throw new Error(`codegen: ${msg}`);
}

function onlyKeys(where, node, allowed) {
  for (const k of Object.keys(node)) if (!allowed.includes(k)) fail(`${where}: unsupported keyword "${k}"`);
}

export function model(schema) {
  onlyKeys("root", schema, ROOT_KEYS);
  const version = schema["x-protocol-version"] ?? fail("no x-protocol-version");
  if (!Number.isSafeInteger(version) || version < 1) fail("x-protocol-version must be a positive integer");
  const defs = schema.$defs ?? fail("no $defs");
  const enums = [];
  const objects = [];
  for (const [name, d] of Object.entries(defs)) {
    if (d.type === "string" && Array.isArray(d.enum)) {
      onlyKeys(name, d, ENUM_KEYS);
      if (!d.enum.every((v) => typeof v === "string" && /^[a-zA-Z_]+$/.test(v))) fail(`${name}: enum values must be words`);
      enums.push({ name, values: d.enum, description: d.description });
      continue;
    }
    if (d.type !== "object") fail(`${name}: unsupported def`);
    onlyKeys(name, d, OBJECT_KEYS);
    if (d.additionalProperties !== false) fail(`${name}: additionalProperties must be false`);
    const markers = Object.keys(CHANNELS).filter((k) => d[k]);
    if (markers.length > 1) fail(`${name}: a message belongs to one channel`);
    const message = markers.length ? d[markers[0]] : undefined;
    const channel = markers.length ? CHANNELS[markers[0]] : undefined;
    const since = d["x-since"] ?? 1;
    if (d["x-since"] !== undefined && !d["x-message"]) fail(`${name}: x-since belongs to a WebSocket message`);
    if (!Number.isSafeInteger(since) || since < 1 || since > version) fail(`${name}: x-since must be an integer in 1..x-protocol-version`);
    if (d["x-write"] !== undefined && d["x-write"] !== true) fail(`${name}: x-write must be the literal true`);
    if (d["x-write"] && !(d["x-message"] ?? "").startsWith("CMD_")) fail(`${name}: x-write belongs to a CMD_* WebSocket message`);
    const write = d["x-write"] === true;
    const required = new Set(d.required ?? []);
    const props = [];
    for (const [pname, p] of Object.entries(d.properties ?? {})) {
      if (pname === "type" && message) {
        onlyKeys(`${name}.type`, p, ["const"]);
        if (p.const !== message) fail(`${name}: type const must equal its message name`);
        continue;
      }
      // plan-phase8 D1 / S7: a field newer than its message — only on a WebSocket message, optional, in (since, version]
      const { "x-since": fieldSince, ...plain } = p;
      if (fieldSince !== undefined) {
        if (!d["x-message"]) fail(`${name}.${pname}: x-since belongs to a property of a WebSocket message`);
        if (!Number.isSafeInteger(fieldSince) || fieldSince <= since || fieldSince > version) {
          fail(`${name}.${pname}: x-since must be an integer newer than its message, up to x-protocol-version`);
        }
        if (required.has(pname)) fail(`${name}.${pname}: x-since on a required property — an older peer never sends it`);
      }
      props.push({ name: pname, type: propType(`${name}.${pname}`, plain, defs), optional: !required.has(pname), since: fieldSince });
    }
    for (const r of required) if (r !== "type" && !props.some((p) => p.name === r)) fail(`${name}: required ${r} missing`);
    if (message && !required.has("type")) fail(`${name}: message must require type`);
    if (message && objects.some((o) => o.message === message)) fail(`${name}: duplicate message name ${message}`);
    objects.push({ name, message, channel, since, write, props, description: d.description });
  }
  const tools = schema["x-tools"] ?? fail("no x-tools");
  // plan-phase2 D4: the oldest version the bridge and native host still serve (half-updated installs, AC9).
  const minVersion = schema["x-protocol-min-version"];
  if (!Number.isSafeInteger(minVersion) || minVersion < 1 || minVersion > version) {
    fail("x-protocol-min-version must be an integer in 1..x-protocol-version");
  }
  return { enums, objects, tools, version, minVersion, relayCloseCodes: relayCloseCodes(schema["x-relay-close-codes"]) };
}

/** plan-relay S1: the relay's own close codes, 4500..4599 (the app uses 4001–4007, Hosting/CloseCodes.cs). */
function relayCloseCodes(codes) {
  if (codes === undefined) return [];
  const where = "x-relay-close-codes";
  if (typeof codes !== "object" || codes === null || Array.isArray(codes)) fail(`${where}: must be an object`);
  const out = [];
  for (const [name, c] of Object.entries(codes)) {
    if (!/^[A-Z][A-Z0-9]*(_[A-Z0-9]+)*$/.test(name)) fail(`${where}: ${name} must be UPPER_SNAKE`);
    if (typeof c !== "object" || c === null) fail(`${where}.${name}: must be an object`);
    onlyKeys(`${where}.${name}`, c, ["code", "description"]);
    if (!Number.isInteger(c.code) || c.code < 4500 || c.code > 4599) fail(`${where}.${name}: code must be an integer in 4500..4599`);
    if (typeof c.description !== "string" || !c.description) fail(`${where}.${name}: needs a description`);
    if (out.some((o) => o.code === c.code)) fail(`${where}.${name}: duplicate code ${c.code}`);
    out.push({ name, code: c.code, description: c.description });
  }
  return out;
}

/** A shorthand class outside the idiom "[\s\S]"; escaped pairs are skipped, so "\\s" is a backslash and an "s". */
function hasShorthandClass(re) {
  for (let i = 0; i < re.length; i++) {
    if (re.startsWith("[\\s\\S]", i)) i += 5;
    else if (re[i] === "\\") {
      if ("sSdDwWbB".includes(re[i + 1])) return true;
      i++;
    }
  }
  return false;
}

function propType(where, p, defs) {
  if (p.$ref) {
    onlyKeys(where, p, PROP_KEYS.ref);
    const ref = p.$ref.replace("#/$defs/", "");
    if (!defs[ref]) fail(`${where}: unknown $ref ${p.$ref}`);
    return { kind: "ref", ref, isEnum: defs[ref].type === "string" };
  }
  const keys = PROP_KEYS[p.type] ?? fail(`${where}: unsupported property ${JSON.stringify(p)}`);
  onlyKeys(where, p, keys);
  switch (p.type) {
    case "array":
      if (!Number.isInteger(p.maxItems)) fail(`${where}: arrays need maxItems`);
      if (p.minItems !== undefined && !(Number.isInteger(p.minItems) && p.minItems >= 0 && p.minItems <= p.maxItems))
        fail(`${where}: minItems must be an integer in 0..maxItems`);
      return { kind: "array", maxItems: p.maxItems, minItems: p.minItems,
        items: propType(`${where}[]`, p.items ?? fail(`${where}: no items`), defs) };
    case "string": {
      if (p.pattern === undefined && p.maxLength === undefined) fail(`${where}: strings need maxLength or pattern`);
      if (p.pattern !== undefined && !(p.pattern.startsWith("^") && p.pattern.endsWith("$"))) fail(`${where}: patterns must be anchored ^…$`);
      if (p.pattern !== undefined && hasShorthandClass(p.pattern)) fail(`${where}: no shorthand class (\\s \\d \\w \\b …) but [\\s\\S] — .NET and JavaScript differ`);
      return { kind: "string", pattern: p.pattern, maxLength: p.maxLength };
    }
    case "integer": {
      for (const k of ["minimum", "maximum"]) {
        if (p[k] !== undefined && !Number.isSafeInteger(p[k])) fail(`${where}: ${k} must be a safe integer`);
      }
      if (p.minimum !== undefined && p.maximum !== undefined && p.minimum > p.maximum) fail(`${where}: minimum > maximum`);
      return { kind: "integer", minimum: p.minimum, maximum: p.maximum };
    }
    default:
      return { kind: p.type };
  }
}

/** The WebSocket messages that carry a field newer than themselves, with those fields: [[message, [[wire name, since]]]]. */
function fieldSince(m) {
  return m.objects
    .filter((o) => o.channel === "ws")
    .map((o) => [o.message, o.props.filter((p) => p.since !== undefined).map((p) => [p.name, p.since])])
    .filter(([, fields]) => fields.length > 0);
}

const pascal = (s) => s[0].toUpperCase() + s.slice(1);
// AUTH_FAILED → AuthFailed, loading → Loading, badProof → BadProof.
const enumMember = (v) => (/^[a-z][a-zA-Z]*$/.test(v) ? pascal(v) : v.toLowerCase().split("_").map(pascal).join(""));

// ---------------------------------------------------------------- C#
function csType(t) {
  switch (t.kind) {
    case "string": return "string";
    case "integer": return "long";
    case "boolean": return "bool";
    case "ref": return t.ref;
    case "array": return `IReadOnlyList<${csType(t.items)}>`;
  }
}

function emitCs(m) {
  const patterns = [];
  const patternId = (re) => {
    // .NET "$" also matches before a final "\n"; "\z" is the true end of the string.
    const net = re.slice(0, -1) + "\\z";
    let i = patterns.indexOf(net);
    if (i < 0) i = patterns.push(net) - 1;
    return `P${i}`;
  };
  const out = [];
  out.push(
    `// <auto-generated>${HEADER}</auto-generated>`,
    "#nullable enable",
    "using System.Text.Json;",
    "using System.Text.Json.Serialization;",
    "using System.Text.RegularExpressions;",
    "",
    "namespace Panda.Bridge.Protocol;",
    "",
  );
  out.push("public static partial class ProtocolInfo", "{", `    public const int Version = ${m.version};`, `    public const int MinVersion = ${m.minVersion};`, "");
  out.push("    /// <summary>The first protocol version of each WebSocket message (schema x-since, plan-phase3 D2).</summary>");
  out.push("    public static readonly IReadOnlyDictionary<string, int> MessageSince = new Dictionary<string, int>(StringComparer.Ordinal)", "    {");
  for (const o of m.objects.filter((x) => x.channel === "ws")) out.push(`        [${JSON.stringify(o.message)}] = ${o.since},`);
  out.push("    };", "");
  out.push("    /// <summary>The fields newer than their message (schema property x-since, plan-phase8 D1): message → wire name → version.</summary>");
  out.push("    public static readonly IReadOnlyDictionary<string, IReadOnlyDictionary<string, int>> FieldSince = new Dictionary<string, IReadOnlyDictionary<string, int>>(StringComparer.Ordinal)", "    {");
  for (const [message, fields] of fieldSince(m)) {
    out.push(`        [${JSON.stringify(message)}] = new Dictionary<string, int>(StringComparer.Ordinal) { ${fields.map(([f, v]) => `[${JSON.stringify(f)}] = ${v}`).join(", ")} },`);
  }
  out.push("    };", "");
  out.push("    /// <summary>The commands with a side effect (schema x-write, plan-phase5a D2): ledger, page queue, no resend across epochs.</summary>");
  out.push("    public static readonly IReadOnlySet<string> Writes = new HashSet<string>(StringComparer.Ordinal)", "    {");
  for (const o of m.objects.filter((x) => x.write)) out.push(`        ${JSON.stringify(o.message)},`);
  out.push("    };", "}", "");
  out.push("public sealed record ToolInfo(string Name, bool SideEffect, int Phase);", "");
  out.push("public static class ToolRegistry", "{", "    public static readonly IReadOnlyList<ToolInfo> All =", "    [");
  for (const t of m.tools) out.push(`        new(${JSON.stringify(t.name)}, ${t.sideEffect}, ${t.phase}),`);
  out.push("    ];", "}", "");
  for (const e of m.enums) {
    if (e.description) out.push(`/// <summary>${e.description}</summary>`);
    out.push(`[JsonConverter(typeof(${e.name}Converter))]`, `public enum ${e.name}`, "{");
    for (const v of e.values) out.push(`    ${enumMember(v)},`);
    out.push("}", "");
    // Exact-string converter: no integers, no comma lists, no case folding (unlike JsonStringEnumConverter).
    out.push(
      `public sealed class ${e.name}Converter : JsonConverter<${e.name}>`,
      "{",
      `    public static string ToWire(${e.name} value) => value switch`,
      "    {",
      ...e.values.map((v) => `        ${e.name}.${enumMember(v)} => ${JSON.stringify(v)},`),
      `        _ => throw new JsonException("undefined ${e.name}"),`,
      "    };",
      "",
      `    public override ${e.name} Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options) =>`,
      `        reader.TokenType == JsonTokenType.String ? reader.GetString() switch`,
      "        {",
      ...e.values.map((v) => `            ${JSON.stringify(v)} => ${e.name}.${enumMember(v)},`),
      `            _ => throw new JsonException("not a ${e.name}"),`,
      `        } : throw new JsonException("${e.name} must be a string");`,
      "",
      `    public override void Write(Utf8JsonWriter writer, ${e.name} value, JsonSerializerOptions options) =>`,
      "        writer.WriteStringValue(ToWire(value));",
      "}",
      "",
    );
  }
  out.push("public interface IMessage", "{", "    string Type { get; }", "}", "");
  out.push("/// <summary>A native-messaging message (plan-native ND3); never an <see cref=\"IMessage\"/>.</summary>");
  out.push("public interface INativeMessage", "{", "    string Type { get; }", "}", "");
  out.push("/// <summary>A relay control message (plan-relay S1); never an <see cref=\"IMessage\"/> or <see cref=\"INativeMessage\"/>.</summary>");
  out.push("public interface IRelayMessage", "{", "    string Type { get; }", "}", "");
  out.push("/// <summary>The relay's own WebSocket close codes (plan-relay S1); never the app's 4001–4007.</summary>");
  out.push("public static class RelayCloseCodes", "{");
  m.relayCloseCodes.forEach((c, i) => {
    if (i) out.push("");
    out.push(`    /// <summary>${c.description}</summary>`, `    public const int ${enumMember(c.name)} = ${c.code};`);
  });
  out.push("}", "");
  for (const o of m.objects) {
    if (o.description) out.push(`/// <summary>${o.description}</summary>`);
    const params = o.props
      .slice()
      .sort((a, b) => Number(a.optional) - Number(b.optional))
      .map((p) => {
        const attrs = [`JsonPropertyName(${JSON.stringify(p.name)})`];
        if (p.optional) attrs.push("JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)");
        return `    [property: ${attrs.join(", ")}] ${csType(p.type)}${p.optional ? "? " : " "}${pascal(p.name)}${p.optional ? " = null" : ""}`;
      });
    const head = `public sealed record ${o.name}`;
    const tail = { ws: " : IMessage", native: " : INativeMessage", relay: " : IRelayMessage" }[o.channel] ?? ";";
    if (params.length === 0) out.push(`${head}()${tail}`);
    else out.push(`${head}(`, params.join(",\n") + `)${tail}`);
    if (o.message) {
      out.push("{", `    public const string TypeName = ${JSON.stringify(o.message)};`, "", '    [JsonPropertyName("type")]', "    public string Type => TypeName;", "}");
    }
    out.push("");
  }
  out.push("public static partial class ProtocolJson", "{", "    private static readonly Dictionary<string, Type> MessageTypes = new(StringComparer.Ordinal)", "    {");
  for (const o of m.objects.filter((x) => x.channel === "ws")) out.push(`        [${o.name}.TypeName] = typeof(${o.name}),`);
  out.push("    };", "");
  out.push("    private static readonly Dictionary<string, Type> NativeMessageTypes = new(StringComparer.Ordinal)", "    {");
  for (const o of m.objects.filter((x) => x.channel === "native")) out.push(`        [${o.name}.TypeName] = typeof(${o.name}),`);
  out.push("    };", "");
  out.push("    private static readonly Dictionary<string, Type> RelayMessageTypes = new(StringComparer.Ordinal)", "    {");
  for (const o of m.objects.filter((x) => x.channel === "relay")) out.push(`        [${o.name}.TypeName] = typeof(${o.name}),`);
  out.push("    };", "}", "");
  // plan-aot A1: Native AOT has no reflection JSON — every protocol type gets source-generated metadata. It is used
  // only as the resolver of ProtocolJson.Options (whose Encoder and strictness flags then apply), never on its own.
  out.push("/// <summary>Source-generated metadata for every protocol object and enum (plan-aot A1).</summary>");
  for (const e of m.enums) out.push(`[JsonSerializable(typeof(${e.name}))]`);
  for (const o of m.objects) out.push(`[JsonSerializable(typeof(${o.name}))]`);
  out.push("public sealed partial class ProtocolJsonContext : JsonSerializerContext", "{", "}", "");
  // Constraints System.Text.Json does not check: patterns, lengths, item counts, integer range, null items.
  out.push("internal static partial class ProtocolValidation", "{");
  const check = (t, acc, name) => {
    switch (t.kind) {
      case "string": return `Str(${acc}, ${t.pattern ? patternId(t.pattern) : "null"}, ${t.maxLength ?? "null"}, ${JSON.stringify(name)})`;
      case "integer": return `Int(${acc}, ${t.minimum ?? "null"}, ${t.maximum ?? "null"}, ${JSON.stringify(name)})`;
      case "ref": return t.isEnum ? null : `FirstViolation(${acc})`;
      case "array": {
        const item = check(t.items, "i", `${name}[]`);
        const min = t.minItems ? `, minItems: ${t.minItems}` : "";
        return `Each(${acc}, ${t.maxItems}, ${JSON.stringify(name)}, i => ${item ?? "null"}${min})`;
      }
      default: return null;
    }
  };
  const body = [];
  for (const o of m.objects) {
    const checks = [];
    for (const p of o.props) {
      const c = check(p.type, `x.${pascal(p.name)}`, p.name);
      if (!c) continue;
      checks.push(p.optional && p.type.kind !== "string" && p.type.kind !== "integer"
        ? `(x.${pascal(p.name)} is null ? null : ${c})`
        : c);
    }
    body.push(`        ${o.name} x => ${checks.length ? checks.join("\n            ?? ") : "null"},`);
  }
  out.push("    public static string? FirstViolation(object? value) => value switch", "    {", '        null => "null value",', ...body, "        _ => null,", "    };", "");
  patterns.forEach((re, i) => out.push(`    private static readonly Regex P${i} = new(${JSON.stringify(re)}, RegexOptions.CultureInvariant);`));
  out.push(
    "",
    "    private const long MaxSafeInteger = 9007199254740991;",
    "",
    "    private static string? Str(string? value, Regex? re, int? maxLength, string name) =>",
    "        value is null ? null",
    "        : maxLength is { } max && value.Length > max ? $\"{name} longer than {max}\"",
    "        : re is not null && !re.IsMatch(value) ? $\"{name} does not match {re}\"",
    "        : null;",
    "",
    "    private static string? Int(long? value, long? minimum, long? maximum, string name) =>",
    "        value is null ? null",
    "        : value is not (>= -MaxSafeInteger and <= MaxSafeInteger) ? $\"{name} outside the safe integer range\"",
    "        : minimum is { } min && value < min ? $\"{name} below {min}\"",
    "        : maximum is { } max && value > max ? $\"{name} above {max}\"",
    "        : null;",
    "",
    "    private static string? Each<T>(IReadOnlyList<T>? items, int maxItems, string name, Func<T, string?> check, int minItems = 0) =>",
    "        items is null ? null",
    "        : items.Count > maxItems ? $\"{name} has more than {maxItems} items\"",
    "        : items.Count < minItems ? $\"{name} has fewer than {minItems} items\"",
    "        : items.Select(i => i is null ? $\"{name} contains null\" : check(i)).FirstOrDefault(v => v is not null);",
    "}",
    "",
  );
  return out.join("\n");
}

// ---------------------------------------------------------------- TypeScript
function tsType(t) {
  switch (t.kind) {
    case "string": return "string";
    case "integer": return "number";
    case "boolean": return "boolean";
    case "ref": return t.ref;
    case "array": return `${tsType(t.items)}[]`;
  }
}

function tsCheck(t, expr, path) {
  switch (t.kind) {
    case "string": {
      const re = t.pattern ? `/${t.pattern.replaceAll("/", "\\/")}/` : "undefined";
      return `str(${expr}, ${path}, ${re}, ${t.maxLength ?? "undefined"})`;
    }
    case "integer": return `int(${expr}, ${path}, ${t.minimum ?? "undefined"}, ${t.maximum ?? "undefined"})`;
    case "boolean": return `bool(${expr}, ${path})`;
    case "ref": return `check${t.ref}(${expr}, ${path})`;
    case "array": return `arr(${expr}, ${path}, ${t.maxItems}, (v, p) => ${tsCheck(t.items, "v", "p")}${t.minItems ? `, ${t.minItems}` : ""})`;
  }
}

function emitTs(m) {
  const out = [`// ${HEADER}`, "/* eslint-disable */", "", `export const PROTOCOL_VERSION = ${m.version};`, `export const PROTOCOL_MIN_VERSION = ${m.minVersion};`, ""];
  out.push("export interface ToolInfo {", "  readonly name: string;", "  readonly sideEffect: boolean;", "  readonly phase: number;", "}", "");
  out.push(`export const TOOLS: readonly ToolInfo[] = ${JSON.stringify(m.tools)};`, "");
  for (const e of m.enums) {
    out.push(`export const ${e.name.toUpperCase()}_VALUES = ${JSON.stringify(e.values)} as const;`);
    out.push(`export type ${e.name} = (typeof ${e.name.toUpperCase()}_VALUES)[number];`, "");
  }
  for (const o of m.objects) {
    if (o.description) out.push(`/** ${o.description} */`);
    out.push(`export interface ${o.name} {`);
    if (o.message) out.push(`  type: ${JSON.stringify(o.message)};`);
    for (const p of o.props) {
      const max = p.type.maxLength ? ` /** ≤ ${p.type.maxLength} UTF-16 units */`
        : p.type.maxItems ? ` /** ${p.type.minItems ? `${p.type.minItems}..` : "≤ "}${p.type.maxItems} items */` : "";
      out.push(`  ${p.name}${p.optional ? "?" : ""}: ${tsType(p.type)};${max}`);
    }
    out.push("}", "");
  }
  const msgs = m.objects.filter((o) => o.channel === "ws");
  const natives = m.objects.filter((o) => o.channel === "native");
  const relays = m.objects.filter((o) => o.channel === "relay");
  out.push(`export type Message = ${msgs.map((o) => o.name).join(" | ")};`, "");
  out.push(`/** Native-messaging channel (plan-native ND3): disjoint from Message. */`);
  out.push(`export type NativeMessage = ${natives.map((o) => o.name).join(" | ")};`, "");
  out.push(`export const NATIVE_MESSAGE_TYPES = ${JSON.stringify(natives.map((o) => o.message))} as const;`, "");
  out.push(`/** Relay control channel (plan-relay S1): disjoint from Message and NativeMessage. */`);
  out.push(`export type RelayMessage = ${relays.map((o) => o.name).join(" | ")};`, "");
  out.push(`export const RELAY_MESSAGE_TYPES = ${JSON.stringify(relays.map((o) => o.message))} as const;`, "");
  out.push(`/** The relay's own WebSocket close codes (plan-relay S1); never the app's 4001–4007. */`);
  out.push("export const RELAY_CLOSE_CODES = {");
  for (const c of m.relayCloseCodes) out.push(`  /** ${c.description} */`, `  ${c.name}: ${c.code},`);
  out.push("} as const;", "");
  out.push(`export type MessageType = Message["type"];`, "");
  out.push(`/** The first protocol version of each message (schema x-since, plan-phase3 D2). */`);
  out.push(`export const MESSAGE_SINCE: Readonly<Record<MessageType, number>> = ${JSON.stringify(Object.fromEntries(msgs.map((o) => [o.message, o.since])))};`, "");
  out.push(`/** The fields newer than their message (schema property x-since, plan-phase8 D1): message → wire name → version. */`);
  out.push(`export const FIELD_SINCE: Readonly<Partial<Record<MessageType, Readonly<Record<string, number>>>>> = ${JSON.stringify(Object.fromEntries(fieldSince(m).map(([k, f]) => [k, Object.fromEntries(f)])))};`, "");
  out.push(`/** The commands with a side effect (schema x-write, plan-phase5a D2): ledger, serializer, no resend across epochs. */`);
  out.push(`export const WRITE_MESSAGES: ReadonlySet<MessageType> = new Set<MessageType>(${JSON.stringify(msgs.filter((o) => o.write).map((o) => o.message))});`, "");
  out.push(
    "export type ParseResult =",
    '  | { kind: "ok"; message: Message }',
    '  | { kind: "unknown"; type: string }',
    '  | { kind: "invalid"; reason: string };',
    "",
    "class Invalid extends Error {}",
    "const fail = (path: string, what: string): never => {",
    "  throw new Invalid(`${path}: ${what}`);",
    "};",
    "const isObj = (v: unknown): v is Record<string, unknown> => typeof v === \"object\" && v !== null && !Array.isArray(v);",
    "function str(v: unknown, path: string, re: RegExp | undefined, maxLength: number | undefined): string {",
    "  if (typeof v !== \"string\") return fail(path, \"expected string\");",
    "  if (!v.isWellFormed()) return fail(path, \"lone surrogate\");",
    "  if (maxLength !== undefined && v.length > maxLength) return fail(path, `longer than ${maxLength}`);",
    "  if (re && !re.test(v)) return fail(path, `does not match ${re.source}`);",
    "  return v;",
    "}",
    "function int(v: unknown, path: string, minimum: number | undefined, maximum: number | undefined): number {",
    "  if (!Number.isSafeInteger(v)) return fail(path, \"expected safe integer\");",
    "  if (minimum !== undefined && (v as number) < minimum) return fail(path, `below ${minimum}`);",
    "  if (maximum !== undefined && (v as number) > maximum) return fail(path, `above ${maximum}`);",
    "  return v as number;",
    "}",
    "function bool(v: unknown, path: string): boolean {",
    "  return typeof v === \"boolean\" ? v : fail(path, \"expected boolean\");",
    "}",
    "function arr<T>(v: unknown, path: string, maxItems: number, item: (v: unknown, p: string) => T, minItems = 0): T[] {",
    "  if (!Array.isArray(v)) return fail(path, \"expected array\");",
    "  if (v.length > maxItems) return fail(path, `more than ${maxItems} items`);",
    "  if (v.length < minItems) return fail(path, `fewer than ${minItems} items`);",
    "  return v.map((x, i) => item(x, `${path}[${i}]`));",
    "}",
    "function obj(v: unknown, path: string, allowed: readonly string[], required: readonly string[]): Record<string, unknown> {",
    "  if (!isObj(v)) return fail(path, \"expected object\");",
    "  for (const k of Object.keys(v)) if (!allowed.includes(k)) fail(`${path}.${k}`, \"unexpected property\");",
    "  for (const k of required) if (!Object.hasOwn(v, k)) fail(`${path}.${k}`, \"missing\");",
    "  return v;",
    "}",
    "",
  );
  for (const e of m.enums) {
    out.push(
      `function check${e.name}(v: unknown, path: string): ${e.name} {`,
      `  return (${e.name.toUpperCase()}_VALUES as readonly unknown[]).includes(v) ? (v as ${e.name}) : fail(path, "not a ${e.name}");`,
      "}",
      "",
    );
  }
  for (const o of m.objects) {
    const allowed = [...(o.message ? ["type"] : []), ...o.props.map((p) => p.name)];
    const required = [...(o.message ? ["type"] : []), ...o.props.filter((p) => !p.optional).map((p) => p.name)];
    out.push(`export function check${o.name}(v: unknown, path: string): ${o.name} {`);
    out.push(`  const o = obj(v, path, ${JSON.stringify(allowed)}, ${JSON.stringify(required)});`);
    for (const p of o.props) {
      const c = tsCheck(p.type, `o.${p.name}`, `path + ".${p.name}"`);
      out.push(p.optional ? `  if (Object.hasOwn(o, ${JSON.stringify(p.name)})) ${c};` : `  ${c};`);
    }
    out.push(`  return o as unknown as ${o.name};`, "}", "");
  }
  out.push("const MESSAGE_CHECKS: Record<string, (v: unknown, path: string) => Message> = {");
  for (const o of msgs) out.push(`  ${JSON.stringify(o.message)}: check${o.name},`);
  out.push("};", "");
  out.push("const NATIVE_CHECKS: Record<string, (v: unknown, path: string) => NativeMessage> = {");
  for (const o of natives) out.push(`  ${JSON.stringify(o.message)}: check${o.name},`);
  out.push("};", "");
  out.push("const RELAY_CHECKS: Record<string, (v: unknown, path: string) => RelayMessage> = {");
  for (const o of relays) out.push(`  ${JSON.stringify(o.message)}: check${o.name},`);
  out.push("};", "");
  out.push(
    "export type NativeParseResult =",
    '  | { kind: "ok"; message: NativeMessage }',
    '  | { kind: "unknown"; type: string }',
    '  | { kind: "invalid"; reason: string };',
    "",
    "/** Validates one message received on a native port (already JSON-decoded by Chrome). Never throws. */",
    "export function parseNativeMessage(value: unknown): NativeParseResult {",
    "  if (!isObj(value) || typeof value.type !== \"string\" || !value.type.isWellFormed()) {",
    "    return { kind: \"invalid\", reason: \"missing type\" };",
    "  }",
    "  const check = Object.hasOwn(NATIVE_CHECKS, value.type) ? NATIVE_CHECKS[value.type] : undefined;",
    "  if (!check) return { kind: \"unknown\", type: value.type };",
    "  try {",
    "    return { kind: \"ok\", message: check(value, value.type) };",
    "  } catch (e) {",
    "    if (e instanceof Invalid) return { kind: \"invalid\", reason: e.message };",
    "    throw e;",
    "  }",
    "}",
    "",
    "/** Returns a validated plain copy (lone surrogates → U+FFFD) to post on a native port. Throws on an invalid message. */",
    "export function toNativeMessage(message: NativeMessage): NativeMessage {",
    "  const copy: unknown = JSON.parse(JSON.stringify(message, (_k, v: unknown) => (typeof v === \"string\" ? v.toWellFormed() : v)));",
    "  const result = parseNativeMessage(copy);",
    "  if (result.kind !== \"ok\") throw new Error(`refusing to send ${message.type}: ${result.kind === \"invalid\" ? result.reason : \"unknown type\"}`);",
    "  return result.message;",
    "}",
    "",
  );
  out.push(
    "/** Parses one WebSocket text frame against one channel's checks. Never throws. */",
    "function parseText<T>(text: string, checks: Record<string, (v: unknown, path: string) => T>):",
    "  | { kind: \"ok\"; message: T }",
    "  | { kind: \"unknown\"; type: string }",
    "  | { kind: \"invalid\"; reason: string } {",
    "  let value: unknown;",
    "  try {",
    "    value = JSON.parse(text);",
    "  } catch {",
    "    return { kind: \"invalid\", reason: \"not JSON\" };",
    "  }",
    "  if (!isObj(value) || typeof value.type !== \"string\" || !value.type.isWellFormed()) {",
    "    return { kind: \"invalid\", reason: \"missing type\" };",
    "  }",
    "  const check = Object.hasOwn(checks, value.type) ? checks[value.type] : undefined;",
    "  if (!check) return { kind: \"unknown\", type: value.type };",
    "  try {",
    "    return { kind: \"ok\", message: check(value, value.type) };",
    "  } catch (e) {",
    "    if (e instanceof Invalid) return { kind: \"invalid\", reason: e.message };",
    "    throw e;",
    "  }",
    "}",
    "",
    "/** Parses one WebSocket text frame. Never throws (S1: unknown types are detectable without an exception). */",
    "export function parseMessage(text: string): ParseResult {",
    "  return parseText(text, MESSAGE_CHECKS);",
    "}",
    "",
    "/**",
    " * Serializes a message after replacing lone surrogates with U+FFFD (a page title can contain them) and",
    " * validating it against the schema. Throws on an invalid message — e.g. an extra `tabId` property — so",
    " * nothing outside the schema ever reaches the wire (spec §5, §71.6).",
    " */",
    "export function serializeMessage(message: Message): string {",
    "  const text = JSON.stringify(message, (_k, v: unknown) => (typeof v === \"string\" ? v.toWellFormed() : v));",
    "  const result = parseMessage(text);",
    "  if (result.kind !== \"ok\") throw new Error(`refusing to send ${message.type}: ${result.kind === \"invalid\" ? result.reason : \"unknown type\"}`);",
    "  return text;",
    "}",
    "",
    "export type RelayParseResult =",
    '  | { kind: "ok"; message: RelayMessage }',
    '  | { kind: "unknown"; type: string }',
    '  | { kind: "invalid"; reason: string };',
    "",
    "/** Parses one relay control text frame (plan-relay S1). Never throws. */",
    "export function parseRelayMessage(text: string): RelayParseResult {",
    "  return parseText(text, RELAY_CHECKS);",
    "}",
    "",
    "/** Serializes a relay control message after validating it. Throws on an invalid message. */",
    "export function serializeRelayMessage(message: RelayMessage): string {",
    "  const text = JSON.stringify(message, (_k, v: unknown) => (typeof v === \"string\" ? v.toWellFormed() : v));",
    "  const result = parseRelayMessage(text);",
    "  if (result.kind !== \"ok\") throw new Error(`refusing to send ${message.type}: ${result.kind === \"invalid\" ? result.reason : \"unknown type\"}`);",
    "  return text;",
    "}",
    "",
  );
  return out.join("\n");
}

/** Go identifier for a schema word: "relayId" → "RelayId", "PROTOCOL_ERROR" → "ProtocolError". */
const goName = (s) => (/^[A-Z0-9_]+$/.test(s) ? s.toLowerCase().split("_").map(pascal).join("") : pascal(s));

function goType(t) {
  switch (t.kind) {
    case "string": return "string";
    case "integer": return "int64";
    case "boolean": return "bool";
    case "ref": return t.ref;
    default: fail(`go output: unsupported ${t.kind} in a relay message`);
  }
}

/**
 * plan-relay-go D7: the relay channel for the Go relay — types, close codes, a strict check per message (the JSON
 * reader and the helpers are relay-go/internal/protocol/json.go, protocol-agnostic) and a marshal per message.
 */
function emitGo(m) {
  const relays = m.objects.filter((o) => o.channel === "relay");
  const enumNames = new Set(relays.flatMap((o) => o.props.filter((p) => p.type.kind === "ref").map((p) => p.type.ref)));
  const enums = m.enums.filter((e) => enumNames.has(e.name));
  const patterns = [...new Set(relays.flatMap((o) => o.props.filter((p) => p.type.pattern).map((p) => p.type.pattern)))];
  const re = (p) => `rePattern${patterns.indexOf(p)}`;
  // gofmt alignment: names in a run of lines are padded with spaces to the longest one + 1 (Go's tabwriter)
  const aligned = (rows) => {
    const w = Math.max(...rows.map(([n]) => n.length));
    return rows.map(([n, rest]) => `\t${n.padEnd(w)} ${rest}`);
  };
  const goList = (xs) => `[]string{${xs.map((x) => JSON.stringify(x)).join(", ")}}`;
  const out = [`// Code generated by schema/codegen.mjs from schema/protocol.v1.json. DO NOT EDIT.`, "", "package protocol", "", 'import "regexp"', ""];
  const line = (s) => s.replaceAll("\r", " ").replaceAll("\n", " "); // a description inside one // comment line
  for (const c of m.relayCloseCodes) out.push(`// Close${goName(c.name)}: ${line(c.description)}`, `const Close${goName(c.name)} = ${c.code}`, "");
  for (const e of enums) {
    out.push(`// ${e.name}: ${line(e.description ?? e.name)}`, `type ${e.name} string`, "", "const (");
    out.push(...aligned(e.values.map((v) => [`${e.name}${enumMember(v)}`, `${e.name} = ${JSON.stringify(v)}`])));
    out.push(")", "", `var values${e.name} = map[string]bool{${e.values.map((v) => `${JSON.stringify(v)}: true`).join(", ")}}`, "");
  }
  if (patterns.length > 0) {
    out.push("var (");
    out.push(...aligned(patterns.map((p) => [re(p), `= regexp.MustCompile(${JSON.stringify(p)})`])));
    out.push(")", "");
  }
  for (const o of relays) {
    out.push(`// ${o.name} is ${o.message}${o.description ? `: ${line(o.description)}` : ""}`, `type ${o.name} struct {`);
    if (o.props.length > 0) out.push(...aligned(o.props.map((p) => [goName(p.name), `${p.optional ? "*" : ""}${goType(p.type)}`])));
    out.push("}", "", `// RelayType is ${JSON.stringify(o.message)}.`, `func (${o.name}) RelayType() string { return ${JSON.stringify(o.message)} }`, "");
    const allowed = ["type", ...o.props.map((p) => p.name)];
    const required = ["type", ...o.props.filter((p) => !p.optional).map((p) => p.name)];
    out.push(`func check${o.name}(o object) (RelayMessage, error) {`, `\tvar m ${o.name}`);
    out.push(`\tif err := o.only(${goList(allowed)}, ${goList(required)}); err != nil {`, "\t\treturn nil, err", "\t}");
    for (const [i, p] of o.props.entries()) {
      const name = JSON.stringify(p.name);
      let read;
      switch (p.type.kind) {
        case "string": read = `o.str(${name}, ${p.type.pattern ? re(p.type.pattern) : "nil"}, ${p.type.maxLength ?? -1})`; break;
        case "integer": read = `o.integer(${name}, ${p.type.minimum !== undefined ? `ptr(${p.type.minimum})` : "nil"}, ${p.type.maximum !== undefined ? `ptr(${p.type.maximum})` : "nil"})`; break;
        case "boolean": read = `o.boolean(${name})`; break;
        case "ref": read = `o.enum(${name}, values${p.type.ref})`; break;
      }
      // a required field reads into its own v<i> (one function scope); an optional one into v inside its if block
      const v = p.optional ? "v" : `v${i}`;
      const conv = p.type.kind === "ref" ? `${p.type.ref}(${v})` : v;
      if (p.optional) out.push(`\tif o.has(${name}) {`);
      const pad = p.optional ? "\t\t" : "\t";
      out.push(`${pad}${v}, err := ${read}`, `${pad}if err != nil {`, `${pad}\treturn nil, err`, `${pad}}`);
      out.push(p.optional ? `${pad}c := ${conv}` : `${pad}m.${goName(p.name)} = ${conv}`);
      if (p.optional) out.push(`${pad}m.${goName(p.name)} = &c`, "\t}");
    }
    out.push("\treturn m, nil", "}", "");
    out.push(`func (m ${o.name}) write(w *writer) {`, `\tw.begin(${JSON.stringify(o.message)})`);
    for (const p of o.props) {
      const name = JSON.stringify(p.name);
      const call = { string: "str", integer: "integer", boolean: "boolean", ref: "str" }[p.type.kind];
      const val = (v) => (p.type.kind === "ref" ? `string(${v})` : v);
      if (p.optional) out.push(`\tif m.${goName(p.name)} != nil {`, `\t\tw.${call}(${name}, ${val(`*m.${goName(p.name)}`)})`, "\t}");
      else out.push(`\tw.${call}(${name}, ${val(`m.${goName(p.name)}`)})`);
    }
    out.push("\tw.end()", "}", "");
  }
  out.push("var relayChecks = map[string]func(object) (RelayMessage, error){");
  out.push(...aligned(relays.map((o) => [`${JSON.stringify(o.message)}:`, `check${o.name},`])));
  out.push("}", "");
  return out.join("\n");
}

// Each output is emitted when read: `--only=cs` never runs the Go emitter (a schema it cannot express fails only `go`).
export function generate(m = model(JSON.parse(readFileSync(join(root, "schema/protocol.v1.json"), "utf8")))) {
  return {
    get cs() { return emitCs(m); },
    get ts() { return emitTs(m); },
    get go() { return emitGo(m); },
  };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  // plan-oss-relay D4: `--only=cs|ts` limits the run to one output (the exported relay repo has no extension/);
  // without it both outputs are written / checked
  const only = process.argv.filter((a) => a.startsWith("--only")).map((a) => a.slice("--only=".length));
  if (only.length > 1 || (only.length === 1 && !Object.hasOwn(OUTPUTS, only[0]))) {
    console.error(`--only takes one of: ${Object.keys(OUTPUTS).join(", ")} (as --only=<name>)`);
    process.exit(2);
  }
  const gen = generate();
  const check = process.argv.includes("--check");
  let stale = false;
  for (const [k, path] of Object.entries(OUTPUTS)) {
    if (only.length === 1 && k !== only[0]) continue;
    let current = null;
    try {
      current = readFileSync(path, "utf8");
    } catch {}
    const text = gen[k];
    if (current === text) continue;
    if (check) {
      console.error(`stale: ${path}`);
      stale = true;
    } else {
      writeFileSync(path, text);
      console.log(`wrote ${path}`);
    }
  }
  if (stale) process.exit(1);
}
